/**
 * Waveform peaks and timeline thumbnails (§4.3.5, R1.20, R1.44), generated by the media utility
 * in the background after a project is ready.
 *
 * Finalize (and recovery) write `project.json` and open the editor as soon as the files are
 * remuxed, probed and drift-fitted; the caches follow here. One queue serves both that background
 * pass and the editor's on-demand requests (`media.peaks`, `media.thumbs`), so an asset is never
 * generated twice at once: a request for an asset that is queued or running just waits for it.
 *
 * Low priority: at most `concurrency` jobs run at a time (peaks first, they are quick), and no new
 * job starts while a recording is being captured (`setHeld`), so the caches of the previous
 * project never compete with the encoders.
 */
import { promises as fs } from 'node:fs';
import path from 'node:path';
import type { JobResult, JobSpec } from '../../shared/ipc/media-utility';
import type { Logger } from '../../shared/logger';
import { silentLogger } from '../../shared/logger';
import type { Media } from '../../shared/project/schema';

export type CacheKind = 'peaks' | 'thumbs';

export const CACHE_DIR_NAME = 'cache';

/** `cache/<mediaId>.peaks` or `cache/<mediaId>.thumbs.json` (relative to the project root). */
export function assetRelativePath(kind: CacheKind, mediaId: string): string {
  return `${CACHE_DIR_NAME}/${mediaId}.${kind === 'peaks' ? 'peaks' : 'thumbs.json'}`;
}

/** The cache a media gets: peaks for audio, thumbnails for video. */
export function cacheKindOf(media: Pick<Media, 'kind'>): CacheKind {
  return media.kind === 'audio' ? 'peaks' : 'thumbs';
}

export type CacheJobRunner = <K extends 'peaks' | 'thumbnails'>(
  job: Extract<JobSpec, { kind: K }>,
) => Promise<JobResult<K>>;

export interface CacheJobsOptions {
  runJob: CacheJobRunner;
  /** Jobs running at once (default 2: an audio and a video job can overlap). */
  concurrency?: number;
  logger?: Logger;
}

export interface CacheRequest {
  projectId: string;
  root: string;
  media: Pick<Media, 'id' | 'kind' | 'path'>;
}

interface Task {
  key: string;
  request: CacheRequest;
  /** Lower runs first. */
  priority: number;
  promise: Promise<void>;
  resolve: () => void;
  reject: (error: unknown) => void;
}

async function isFile(fullPath: string): Promise<boolean> {
  const stat = await fs.stat(fullPath).catch(() => null);
  return stat?.isFile() ?? false;
}

export class CacheJobs {
  private readonly tasks = new Map<string, Task>();
  private readonly queue: Task[] = [];
  private readonly failed = new Set<string>();
  private running = 0;
  private held = false;
  private readonly logger: Logger;

  constructor(private readonly options: CacheJobsOptions) {
    this.logger = options.logger ?? silentLogger;
  }

  static key(projectId: string, mediaId: string, kind: CacheKind): string {
    return `${projectId}:${mediaId}:${kind}`;
  }

  /** Queued or running. */
  isPending(projectId: string, mediaId: string, kind: CacheKind): boolean {
    return this.tasks.has(CacheJobs.key(projectId, mediaId, kind));
  }

  /** The last attempt failed (cleared by `clearFailures`, e.g. after a relink). */
  hasFailed(projectId: string, mediaId: string, kind: CacheKind): boolean {
    return this.failed.has(CacheJobs.key(projectId, mediaId, kind));
  }

  clearFailures(projectId?: string): void {
    if (projectId === undefined) this.failed.clear();
    else
      for (const key of [...this.failed])
        if (key.startsWith(`${projectId}:`)) this.failed.delete(key);
  }

  /** While held, queued jobs wait (running ones finish). */
  setHeld(held: boolean): void {
    if (this.held === held) return;
    this.held = held;
    if (!held) this.pump();
  }

  /**
   * Generates one media's cache unless it is already queued or running (then the same promise is
   * returned). Rejects when the job fails.
   */
  ensure(request: CacheRequest, priority = 1): Promise<void> {
    const promise = this.enqueue(request, priority);
    this.pump();
    return promise;
  }

  private enqueue(request: CacheRequest, priority: number): Promise<void> {
    const kind = cacheKindOf(request.media);
    const key = CacheJobs.key(request.projectId, request.media.id, kind);
    const existing = this.tasks.get(key);
    if (existing) {
      if (priority < existing.priority && this.queue.includes(existing)) {
        existing.priority = priority;
        this.sortQueue();
      }
      return existing.promise;
    }
    let resolve!: () => void;
    let reject!: (error: unknown) => void;
    const promise = new Promise<void>((res, rej) => {
      resolve = res;
      reject = rej;
    });
    // Callers that only start the job need not handle its failure (it is logged).
    promise.catch(() => undefined);
    const task: Task = { key, request, priority, promise, resolve, reject };
    this.tasks.set(key, task);
    this.failed.delete(key);
    this.queue.push(task);
    this.sortQueue();
    return promise;
  }

  /**
   * The background pass after finalize or recovery: every usable media whose cache file is
   * missing, peaks before thumbnails. Resolves when all are done (failures are only logged).
   */
  async generateAll(projectId: string, root: string, media: readonly Media[]): Promise<void> {
    const usable = media.filter(
      (m) => m.status !== 'failed' && m.status !== 'missing' && m.durationUs > 0,
    );
    const exists = await Promise.all(
      usable.map((m) =>
        isFile(path.join(root, ...assetRelativePath(cacheKindOf(m), m.id).split('/'))),
      ),
    );
    // Queued together, so the priorities (peaks first) decide the order.
    const wanted = usable
      .filter((_, i) => !exists[i])
      .map((m) => this.enqueue({ projectId, root, media: m }, cacheKindOf(m) === 'peaks' ? 1 : 2));
    this.pump();
    await Promise.allSettled(wanted);
  }

  private sortQueue(): void {
    this.queue.sort((a, b) => a.priority - b.priority);
  }

  private pump(): void {
    const limit = Math.max(1, this.options.concurrency ?? 2);
    while (!this.held && this.running < limit && this.queue.length > 0) {
      const task = this.queue.shift();
      if (!task) break;
      this.running += 1;
      void this.run(task).finally(() => {
        this.running -= 1;
        this.tasks.delete(task.key);
        this.pump();
      });
    }
  }

  private async run(task: Task): Promise<void> {
    const { root, media } = task.request;
    const kind = cacheKindOf(media);
    const input = path.join(root, ...media.path.split('/'));
    const cacheDir = path.join(root, CACHE_DIR_NAME);
    try {
      if (kind === 'peaks') {
        await fs.mkdir(cacheDir, { recursive: true });
        await this.options.runJob({
          kind: 'peaks',
          input,
          output: path.join(root, ...assetRelativePath('peaks', media.id).split('/')),
        });
      } else {
        // The thumbnails job creates its output folder itself.
        await this.options.runJob({
          kind: 'thumbnails',
          input,
          outDir: cacheDir,
          mediaId: media.id,
        });
      }
      task.resolve();
    } catch (error) {
      this.failed.add(task.key);
      this.logger.warn(`caches: ${kind} for ${media.id} failed`, error);
      task.reject(error);
    }
  }
}
